// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNumber, uint256 blockTimestamp, uint256 pastBlockTimeInit) public {
        // Ensure valid block context and timestamp ordering
        vm.assume(blockTimestamp > pastBlockTimeInit);
        vm.assume(blockNumber > 0);
        vm.assume(blockTimestamp > 0);

        // Set initial state: pastBlockTime and block context
        vm.store(address(c), bytes32(uint256(1)), bytes32(pastBlockTimeInit)); // slot 1 is pastBlockTime
        vm.roll(blockNumber);
        vm.warp(blockTimestamp);

        // Record balance before call
        uint256 balanceBefore = address(c).balance;

        // Fund contract with some ether to simulate possible balance changes
        vm.deal(address(c), 10 ether);

        // Make the fallback call with exactly 10 ether
        (bool success, ) = address(c).call{value: 10 ether}("");

        // Rule: if the call succeeded, balanceBefore was >0, and block.number % 15 != 0, then balance should not decrease
        // But we need a general rule: the contract never keeps 10 ether after a successful call when block.number % 15 == 0
        if (success) {
            assertTrue(address(c).balance == 0 || block.number % 15 != 0);
        } else {
            assertTrue(true);
        }
    }
}

